        private static readonly ConstantExpression Unfoldable = new(null);

        private ConstantExpression? _folded;

        internal override ConstantExpression? ConstantFold() {
            _folded ??= Fold() ?? Unfoldable;
            return ReferenceEquals(_folded, Unfoldable) ? null : _folded;
        }

        private ConstantExpression? Fold() {
            var left = Left.ConstantFold()?.Value;
            var right = Right.ConstantFold()?.Value;

            if (left is null || right is null) {
                return null;
            }

            try {
                if (left.GetType() == right.GetType()) {
                    var folded = FoldNumeric(left, right, Operator);
                    if (folded is not null) {
                        return folded;
                    }
                }

                object? res = Operator switch {
                    PythonOperator.Add when left is string l && right is string r
                        && l.Length + r.Length <= MaximumInlineStringLength => l + r,
                    PythonOperator.Add when left is Bytes l && right is Bytes r
                        && l.Count + r.Count <= MaximumInlineStringLength => l + r,
                    PythonOperator.Multiply when left is string s && right is int n => Repeat(s, n),
                    PythonOperator.Multiply when left is int n && right is string s => Repeat(s, n),
                    PythonOperator.Multiply when left is Bytes b && right is int n => RepeatBytes(b, n),
                    PythonOperator.Multiply when left is int n && right is Bytes b => RepeatBytes(b, n),
                    _ => null,
                };
                return res is null ? null : new ConstantExpression(res);
            } catch (ArithmeticException) {
                // e.g. division by zero: leave the expression unfolded so the error is raised if the code runs
            }

            return null;

            static string? Repeat(string s, int n)
                => (long)s.Length * n <= MaximumInlineStringLength ? StringOps.Multiply(s, n) : null;

            static Bytes? RepeatBytes(Bytes b, int n)
                => (long)b.Count * n <= MaximumInlineStringLength ? b * n : null;
        }

